**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <climits>
using namespace std;

int main() {
    ifstream plik("liczby.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();

    // Drugie max (szukamy drugiej unikalnej wartosci)
    int max1 = INT_MIN, max2 = INT_MIN;
    int posMax1 = -1, posMax2 = -1;
    for (int i = 0; i < n; i++) {
        if (tab[i] > max1) {
            max2 = max1; posMax2 = posMax1;
            max1 = tab[i]; posMax1 = i;
        } else if (tab[i] < max1 && tab[i] > max2) {
            max2 = tab[i]; posMax2 = i;
        }
    }

    // Drugie min (szukamy drugiej unikalnej wartosci)
    int min1 = INT_MAX, min2 = INT_MAX;
    int posMin1 = -1, posMin2 = -1;
    for (int i = 0; i < n; i++) {
        if (tab[i] < min1) {
            min2 = min1; posMin2 = posMin1;
            min1 = tab[i]; posMin1 = i;
        } else if (tab[i] > min1 && tab[i] < min2) {
            min2 = tab[i]; posMin2 = i;
        }
    }

    cout << "a) Max: " << max1 << " (pozycja: " << posMax1 + 1 << ")" << endl;
    cout << "   Drugie max: " << max2 << " (pozycja: " << posMax2 + 1 << ")" << endl;
    cout << "b) Min: " << min1 << " (pozycja: " << posMin1 + 1 << ")" << endl;
    cout << "   Drugie min: " << min2 << " (pozycja: " << posMin2 + 1 << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Sledzenie dwoch wartosci (max1/max2 i min1/min2). Kluczowa logika: gdy nowy element > max1, stary max1 przesuwa sie na max2. Gdy element jest miedzy max2 a max1, aktualizujemy tylko max2. Warunek `tab[i] < max1` gwarantuje, ze duplikaty max nie zastepuja drugiego max.

Weryfikacja:
- Max1: 89 (poz.4, 89 na poz.6 jest takie samo — nie nadpisuje). Max2: 78 (poz.9)
- Min1: 11 (poz.10). Min2: 12 (poz.3)
- Posortowane unikatowe: 11,12,23,34,40,45,56,67,78,89 — drugie od gory=78, drugie od dolu=12.
